using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();
        string inputText = args["rawInput"].ToString();

        // Parse wager
        if (string.IsNullOrEmpty(inputText)) {
            CPH.SendMessage($"@{userName}, usage: !roulette [wager]. Example: !roulette 100 (min: 25, max: 1000)");
            return false;
        }

        int wager;
        if (!int.TryParse(inputText, out wager) || wager < 25 || wager > 1000) {
            CPH.SendMessage($"@{userName}, wager must be between 25 and 1000 eggs!");
            return false;
        }

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage($"@{userName}, you don't have any eggs! Start chatting to earn some!");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Check balance
        if (data["users"] == null || data["users"][userId] == null) {
            CPH.SendMessage($"@{userName}, you don't have any eggs! Start chatting to earn some!");
            return false;
        }

        int currentEggs = (int)(data["users"][userId]["eggs"] ?? 0);

        if (currentEggs < wager) {
            CPH.SendMessage($"@{userName}, you don't have enough eggs! You have {currentEggs} eggs.");
            return false;
        }

        // Generate weighted random outcome
        Random rnd = new Random();
        int roll = rnd.Next(1, 101); // 1-100

        int result = 0;
        string outcome = "";
        string emoji = "";
        bool loseToken = false;

        // Weighted probabilities:
        // Jackpot: 5% (1-5)
        // Big Win: 10% (6-15)
        // Win: 20% (16-35)
        // Small Win: 25% (36-60)
        // Push: 15% (61-75)
        // Small Loss: 15% (76-90)
        // Big Loss: 8% (91-98)
        // Catastrophe: 2% (99-100)

        if (roll <= 5) {
            result = wager * 5 + 200;
            outcome = "🌟 JACKPOT! 🌟";
            emoji = "💎";
        } else if (roll <= 15) {
            result = wager * 3;
            outcome = "Big Win!";
            emoji = "🎉";
        } else if (roll <= 35) {
            result = wager * 2;
            outcome = "Win!";
            emoji = "✅";
        } else if (roll <= 60) {
            result = (wager * 3) / 2;
            outcome = "Small Win";
            emoji = "😊";
        } else if (roll <= 75) {
            result = 0;
            outcome = "Push";
            emoji = "😐";
        } else if (roll <= 90) {
            result = -wager;
            outcome = "Small Loss";
            emoji = "😬";
        } else if (roll <= 98) {
            result = -wager;
            int rrTokens = (int)(data["users"][userId]["rrTokens"] ?? 0);
            if (rrTokens > 0) {
                data["users"][userId]["rrTokens"] = rrTokens - 1;
                loseToken = true;
            }
            outcome = "Big Loss";
            emoji = "❌";
        } else {
            // Catastrophe: lose wager + 50% of current eggs (capped at 500)
            int additionalLoss = Math.Min(currentEggs / 2, 500);
            result = -(wager + additionalLoss);
            outcome = "💀 CATASTROPHE! 💀";
            emoji = "💥";
        }

        // Update eggs
        int newEggs = Math.Max(0, currentEggs + result);
        data["users"][userId]["eggs"] = newEggs;

        File.WriteAllText(dataPath, data.ToString());

        // Send message
        string resultStr = result > 0 ? $"+{result}" : result.ToString();
        string message = $"🎰 @{userName} spins the roulette... {emoji} {outcome} Result: {resultStr} eggs!";
        if (loseToken) {
            message += " (-1 RRToken)";
        }
        message += $" Total: {newEggs} 🥚";

        CPH.SendMessage(message);

        return true;
    }
}
